func (d *SiteExplorerDataSource) Configure(_ context.Context, req datasource.ConfigureRequest, resp *datasource.ConfigureResponse) {
	if req.ProviderData == nil {
		return
	}
	client, ok := req.ProviderData.(*Client)
	if !ok {
		resp.Diagnostics.AddError(
			"Unexpected DataSource Configure Type",
			fmt.Sprintf("Expected *Client, got: %T.", req.ProviderData),
		)
		return
	}
	d.client = client
}

func (d *SiteExplorerDataSource) Read(ctx context.Context, req datasource.ReadRequest, resp *datasource.ReadResponse) {
	var data SiteExplorerDataSourceModel
	resp.Diagnostics.Append(req.Config.Get(ctx, &data)...)
	if resp.Diagnostics.HasError() {
		return
	}

	url := d.client.ResolvePath("/v2/org/{org}/nico/site-explorer/endpoint/action", map[string]string{})
	queryParams := map[string]string{}
	queryParams["siteId"] = data.SiteId.ValueString()
	queryParams["machineId"] = data.MachineId.ValueString()
	items, err := d.client.List(ctx, url, queryParams)
	if err != nil {
		resp.Diagnostics.AddError("Error listing Site Explorer", err.Error())
		return
	}
	_ = items
	// TODO: expose items as a list attribute

	resp.Diagnostics.Append(resp.State.Set(ctx, &data)...)
}

func (d *SiteExplorerDataSource) populateModel(ctx context.Context, data *SiteExplorerDataSourceModel, result map[string]interface{}, diags diag.Diagnostics) {
	data.Address = StringFromAPI(result["address"])
	if rawObj_report, ok := result["report"].(map[string]interface{}); ok {
		obj_report := &SiteExplorerDsReport{}
		obj_report.EndpointType = StringFromAPI(rawObj_report["endpointType"])
		obj_report.LastExplorationError = StringFromAPI(rawObj_report["lastExplorationError"])
		obj_report.MachineId = StringFromAPI(rawObj_report["machineId"])
		obj_report.LastExplorationLatency = StringFromAPI(rawObj_report["lastExplorationLatency"])
		obj_report.Vendor = StringFromAPI(rawObj_report["vendor"])
		// managers: nested field — expand manually if needed
		// systems: nested field — expand manually if needed
		// chassis: nested field — expand manually if needed
		// service: nested field — expand manually if needed
		// machineSetupStatus: nested field — expand manually if needed
		// secureBootStatus: nested field — expand manually if needed
		// lockdownStatus: nested field — expand manually if needed
		// firmwareVersions: map field — expand manually if needed
		_ = rawObj_report["firmwareVersions"]
		// lastExplorationErrorSchema: nested field — expand manually if needed
		_ = rawObj_report
		data.Report = obj_report
	} else {
		data.Report = nil
	}
	data.ReportVersion = StringFromAPI(result["reportVersion"])
	data.ExplorationRequested = BoolFromAPI(result["explorationRequested"])
	data.PreingestionState = StringFromAPI(result["preingestionState"])
	data.LastRedfishBmcReset = StringFromAPI(result["lastRedfishBmcReset"])
	data.LastIpmitoolBmcReset = StringFromAPI(result["lastIpmitoolBmcReset"])
	data.LastRedfishReboot = StringFromAPI(result["lastRedfishReboot"])
	data.LastRedfishPowercycle = StringFromAPI(result["lastRedfishPowercycle"])
	data.PauseRemediation = BoolFromAPI(result["pauseRemediation"])
	_ = diags
}
